-- Seeded from Case(4).docx test case library (19 rows)
CREATE TABLE IF NOT EXISTS scam_cases (
    id SERIAL PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    source VARCHAR(512),
    url_link VARCHAR(512),
    scam_type VARCHAR(50) NOT NULL,
    platform VARCHAR(50) NOT NULL,
    news_date DATE NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_scam_cases_scam_type ON scam_cases(scam_type);
CREATE INDEX IF NOT EXISTS idx_scam_cases_platform ON scam_cases(platform);
CREATE INDEX IF NOT EXISTS idx_scam_cases_news_date ON scam_cases(news_date);

INSERT INTO scam_cases (title, content, source, url_link, scam_type, platform, news_date)
SELECT 'Elderly Woman Falls Victim To Online Part-time Job Offer, Loses Over RM500,000', 'A 71-year-old woman in Kuching lost RM527,130 after falling for a fraudulent part-time job offer sent by an unknown individual on TikTok. Lured by the promise of lucrative commissions, she completed "tasks" that required her to make 23 separate transactions to 16 different bank accounts. She only realized it was a scam when the promised returns never materialized. Kuching police revealed that 49 similar cases have been investigated since the start of the year, with total losses reaching RM2.26 million.', 'Bernama', 'https://www.bernama.com/en/news.php?id=2496938', 'JOB_SCAM', 'tiktok', DATE '2025-12-19'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Elderly Woman Falls Victim To Online Part-time Job Offer, Loses Over RM500,000');
INSERT INTO scam_cases (title, content, source, url_link, scam_type, platform, news_date)
SELECT 'Trader Loses Over RM500,000 To Online Job Scam', 'A 38-year-old trader in Kuala Terengganu lost over RM500,000 after being contacted by a Facebook user named "Nabila Puteri." He was lured by a part-time job offering high commissions. To "earn," he was instructed to buy items through a suspicious app. After an initial small commission was paid to gain his trust, he performed 38 more transactions to 22 different bank accounts using his life savings and credit cards.', 'Bernama', 'https://www.bernama.com/en/news.php?id=2443416', 'JOB_SCAM', 'facebook', DATE '2025-05-14'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Trader Loses Over RM500,000 To Online Job Scam');
