SELECT 'Retired Engineer Loses Over RM100,000 In Scam Recovery Ruse', 'In a double-blow case, a retired engineer who had previously lost money to a scam fell for a second scam on Facebook. He clicked an ad promising to "recover lost scam money." The "recovery agents" on WhatsApp convinced him to pay "file opening fees" and "processing charges," leading to an additional loss of RM108,001 via 8 online transfers.', 'The Star', 'https://www.thestar.com.my/news/nation/2026/01/14/retired-engineer-loses-over-rm100000-in-scam-recovery-ruse', 'JOB_SCAM', 'facebook', DATE '2026-01-14'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Retired Engineer Loses Over RM100,000 In Scam Recovery Ruse');
