SELECT 'Beware! Impersonation Of The CEO Of EPF (Feb 12, 2026)', 'Scammers impersonated high-ranking Employees Provident Fund (EPF/KWSP) officials, including the CEO, by sending fraudulent emails and SMS claiming that a "security audit" or "identity synchronization" was mandatory to prevent i-Akaun suspension. Victims were lured into clicking a link to a fake EPF portal, where they unknowingly handed over their passwords and OTPs, allowing scammers to take control of their retirement savings data to change beneficiary details or attempt unauthorized withdrawals.', 'KWSP Official', NULL, 'phishing', 'whatsapp', DATE '2025-02-24'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Beware! Impersonation Of The CEO Of EPF (Feb 12, 2026)');
