SELECT 'QR Code Manipulation: Scammers'' New Tactic To Steal Users'' Data', 'Scammers targeted local food stalls and night markets by pasting their own fraudulent DuitNow QR stickers over the merchants'' original payment codes. Customers who scanned these manipulated codes to pay for their meals unknowingly transferred their money directly into the scammers'' bank accounts rather than to the vendors. PDRM issued a nationwide alert after dozens of merchants in Kuala Lumpur reported a sudden loss of daily earnings due to these physical QR overlays.', 'Bernama', NULL, 'qr_code_scam', 'phone_message', DATE '2025-01-09'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'QR Code Manipulation: Scammers'' New Tactic To Steal Users'' Data');
INSERT INTO scam_cases (title, content, source, url_link, scam_type, platform, news_date)
SELECT 'Manipulasi Kod QR Taktik Scammer Perangkap Pengguna', 'Exploiting the digital "Duit Raya" trend, scammers shared QR codes on WhatsApp promising a government-funded Aidilfitri subsidy of RM500. The scan led to a site that requested a "face scan" or biometric verification to unlock the funds, which was actually a tactic to steal the victim''s facial data and bypass banking security features. This case highlighted a new level of "Quishing" where scammers use QR codes to harvest biometric data for identity theft.', 'Bernama', NULL, 'qr_code_scam', 'whatsapp', DATE '2025-08-14'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Manipulasi Kod QR Taktik Scammer Perangkap Pengguna');
INSERT INTO scam_cases (title, content, source, url_link, scam_type, platform, news_date)
SELECT 'Careless QR Scanning Leads to Data Leaks and Financial Loss', 'At several Malaysian airports and malls, scammers placed QR code stickers on public charging stations promising "Free High-Speed Wi-Fi" for users who scanned them. Instead of providing internet access, the QR code redirected the browser to a page that forced the installation of a hidden "tracking profile" or spyware on the device. This allowed scammers to monitor the victim''s keystrokes and steal login credentials for social media and banking apps in real-time.', 'Bernama', NULL, 'qr_code_scam', 'whatsapp', DATE '2025-08-14'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Careless QR Scanning Leads to Data Leaks and Financial Loss');
INSERT INTO scam_cases (title, content, source, url_link, scam_type, platform, news_date)
SELECT 'Online scammer uses fake ID, QR code to take RM9,000', 'An insurance salesperson in Sibu lost nearly RM9,000 after being lured by a scammer offering a fake installment plan for a prize purchase. To gain her trust, the suspect used a fake employee ID card. The victim was then deceived into scanning a QR code that allowed the suspect to gain illegal access to her accounts. Once scanned, her savings were quickly drained through a series of rapid unauthorized transactions.', 'The Star', NULL, 'qr_code_scam', 'whatsapp', DATE '2026-02-20'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Online scammer uses fake ID, QR code to take RM9,000');
INSERT INTO scam_cases (title, content, source, url_link, scam_type, platform, news_date)
SELECT 'New Scam Alert: Physical Red Packets with Fraudulent QR Codes', 'During the 2026 festive season, Maybank issued an emergency alert regarding physical "Lucky Packets" (Angpao) being distributed in public areas and mailboxes. These packets contained cards with QR codes promising "free lucky money" or "festive rewards." Scanning the code directed victims to a fake website that harvested banking credentials or prompted the download of malicious files, resulting in account takeovers.', 'Maybank2u', NULL, 'qr_code_scam', 'phone_message', DATE '2026-02-20'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'New Scam Alert: Physical Red Packets with Fraudulent QR Codes');
