SELECT 'Two Company Directors In Penang Lose Nearly RM900,000 To Phone Scams', 'A 69-year-old retired clerk in Penang lost RM457,607 after receiving a call from a scammer impersonating an officer from the Malaysian Communications and Multimedia Commission (MCMC). The victim was told her phone number was involved in illegal activities and was coerced into "registering" her bank account for an audit by providing her online banking credentials and multiple OTP/TAC codes. These codes allowed the scammers to gain full control of her account and perform 11 unauthorized transfers within a single afternoon.', 'Bernama', NULL, 'otp_scam', 'whatsapp', DATE '2026-03-27'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Two Company Directors In Penang Lose Nearly RM900,000 To Phone Scams');
