SELECT 'Medical Specialist Loses RM529,200 To Non-Existent Investment Scam', 'A medical specialist in his 50s lost RM529,200 after being contacted by a scammer posing as a "legal assistant" from a reputable bank. The scammer claimed to be helping the specialist recover funds lost in a previous failed investment. To "verify the refund process," the victim was asked to provide his banking username and the OTP codes that arrived on his phone; instead of receiving a refund, his remaining life savings were systematically drained.', 'Bernama', NULL, 'otp_scam', 'tiktok', DATE '2026-01-03'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Medical Specialist Loses RM529,200 To Non-Existent Investment Scam');
