SELECT 'Three Malaysians Detained In Online Scam, 46 Sim Cards Seized', 'PDRM arrested three individuals for a "SIM Swap" syndicate that targeted users of major Malaysian telcos like Maxis and Celcom. Scammers called victims pretending to be technical support, claiming their 4G SIM cards needed a "5G upgrade" to avoid service disruption. They asked the victims to read out a verification code sent via SMS; this code was actually the authorization to port the phone number to a new SIM card, allowing the scammers to intercept all future banking OTPs.', 'Bernama', NULL, 'otp_scam', 'whatsapp', DATE '2026-01-27'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Three Malaysians Detained In Online Scam, 46 Sim Cards Seized');
