SELECT 'Selangor Police Deny Raya Fundraising Event, Confirm Scam Attempt', 'Selangor police warned the public about a viral SMS soliciting donations for a fake "PDRM Hari Raya Event." The message asked people to click a link to donate and then enter their OTP to "verify the charity contribution." Police confirmed that this was a phishing attempt where scammers harvested OTPs to gain access to the victims'' online banking portals under the guise of a charitable act.', 'Bernama', NULL, 'otp_scam', 'whatsapp', DATE '2026-03-25'
WHERE NOT EXISTS (SELECT 1 FROM scam_cases WHERE title = 'Selangor Police Deny Raya Fundraising Event, Confirm Scam Attempt');
